import {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

export interface ValidationResult {
  valid: boolean;
  error?: string;
  data?: IncomingMessage;
}

export function validateMessage(message: unknown): ValidationResult {
  if (typeof message !== 'object' || message === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const record = message as Record<string, unknown>;
  const {type} = record;

  if (typeof type !== 'string') {
    return {valid: false, error: 'Message must have a type string'};
  }

  switch (type) {
    case 'user_message':
      return validateUserMessage(record);
    case 'ping':
      return validatePingMessage(record);
    case 'list_sessions':
      return validateListSessionsMessage(record);
    default:
      return {valid: false, error: `Unknown message type: ${type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  const {content} = message;
  if (typeof content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  if (content.trim().length === 0) {
    return {valid: false, error: 'user_message content must not be empty or blank'};
  }

  if (content.length > 10000) {
    return {valid: false, error: 'user_message content must be at most 10000 characters'};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content,
    },
  };
}

